/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d0d0d;
  --bg2:       #141414;
  --bg3:       #1c1c1c;
  --border:    #2a2a2a;
  --accent:    #e8c96d;
  --accent2:   #c0392b;
  --text:      #f0f0f0;
  --muted:     #888;
  --radius:    6px;
  --font:      'Inter', system-ui, sans-serif;
  --transition: .25s ease;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
button { cursor: pointer; font-family: inherit; }

/* ── Utility ── */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 3px;
}
.badge--accent  { background: var(--accent);  color: #0d0d0d; }
.badge--red     { background: var(--accent2); color: #fff; }
.badge--outline { border: 1px solid var(--border); color: var(--muted); }

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 28px;
  gap: 16px;
}
.section-header h2 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  letter-spacing: -.02em;
}
.section-header a {
  font-size: 13px;
  color: var(--accent);
  white-space: nowrap;
  transition: opacity var(--transition);
}
.section-header a:hover { opacity: .7; }

/* ── Navbar ── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,13,.88);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.navbar__inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 64px;
}
.navbar__logo {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -.03em;
  flex-shrink: 0;
}
.navbar__logo span { color: var(--accent); }

.navbar__nav {
  display: flex;
  gap: 24px;
  list-style: none;
  flex: 1;
}
.navbar__nav a {
  font-size: 13px;
  font-weight: 500;
  color: var(--muted);
  transition: color var(--transition);
}
.navbar__nav a:hover { color: var(--text); }

.navbar__actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-shrink: 0;
}
.navbar__search {
  display: flex;
  align-items: center;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 6px 12px;
  gap: 8px;
}
.navbar__search input {
  background: none;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 13px;
  width: 180px;
}
.navbar__search input::placeholder { color: var(--muted); }
.navbar__search svg { color: var(--muted); flex-shrink: 0; }

.navbar__icon-btn {
  background: none;
  border: none;
  color: var(--muted);
  position: relative;
  padding: 6px;
  border-radius: var(--radius);
  transition: color var(--transition), background var(--transition);
}
.navbar__icon-btn:hover { color: var(--text); background: var(--bg3); }
.navbar__badge {
  position: absolute;
  top: 2px; right: 2px;
  background: var(--accent2);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  pointer-events: none;
}

.navbar__mobile-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text);
  padding: 6px;
}

/* ── Hero ── */
.hero {
  position: relative;
  overflow: hidden;
  min-height: 580px;
  display: flex;
  align-items: center;
  background: var(--bg2);
}
.hero__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 80% 50%, rgba(232,201,109,.10) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 20%, rgba(192,57,43,.08) 0%, transparent 60%);
}
.hero__grid-overlay {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: .35;
}
.hero__inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 80px 0;
}
.hero__kicker {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 16px;
}
.hero__title {
  font-size: clamp(36px, 5vw, 64px);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -.03em;
  margin-bottom: 20px;
}
.hero__title em { font-style: normal; color: var(--accent); }
.hero__sub {
  font-size: 17px;
  color: var(--muted);
  max-width: 440px;
  margin-bottom: 36px;
  line-height: 1.7;
}
.hero__ctas { display: flex; gap: 14px; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 600;
  border: none;
  transition: transform var(--transition), opacity var(--transition), box-shadow var(--transition);
}
.btn:hover { transform: translateY(-1px); opacity: .9; }
.btn--primary {
  background: var(--accent);
  color: #0d0d0d;
  box-shadow: 0 4px 20px rgba(232,201,109,.25);
}
.btn--primary:hover { box-shadow: 0 6px 28px rgba(232,201,109,.4); }
.btn--ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--ghost:hover { background: var(--bg3); }

.hero__image-wrap {
  position: relative;
  display: flex;
  justify-content: center;
}
.hero__product-card {
  position: relative;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  width: 100%;
  max-width: 420px;
  aspect-ratio: 4/5;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.hero__product-img {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 130px;
  line-height: 1;
  filter: drop-shadow(0 20px 40px rgba(0,0,0,.6));
  padding-top: 40px;
}
.hero__product-info {
  position: relative;
  background: linear-gradient(transparent, rgba(13,13,13,.92) 40%);
  padding: 40px 24px 28px;
}
.hero__product-info h3 { font-size: 22px; font-weight: 700; margin-bottom: 6px; }
.hero__product-info p { color: var(--muted); font-size: 14px; margin-bottom: 14px; }
.hero__price { font-size: 24px; font-weight: 800; color: var(--accent); }
.hero__price s { font-size: 16px; color: var(--muted); font-weight: 400; margin-left: 8px; }

.hero__floating-badge {
  position: absolute;
  top: 20px; right: 20px;
  background: var(--accent2);
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  padding: 8px 14px;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(192,57,43,.4);
}

/* ── Marquee ticker ── */
.ticker {
  background: var(--accent);
  color: #0d0d0d;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
}
.ticker__track {
  display: inline-block;
  animation: ticker 28s linear infinite;
}
.ticker__track span { margin: 0 32px; }
@keyframes ticker { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ── Sections ── */
section { padding: 72px 0; }
section + section { border-top: 1px solid var(--border); }

/* ── Featured Products ── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}
.product-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  transition: transform var(--transition), border-color var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.product-card:hover {
  transform: translateY(-4px);
  border-color: rgba(232,201,109,.3);
  box-shadow: 0 12px 40px rgba(0,0,0,.4);
}
.product-card__image {
  aspect-ratio: 1;
  background: var(--bg3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
  position: relative;
  overflow: hidden;
}
.product-card__image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 60%, rgba(232,201,109,.04));
}
.product-card__wishlist {
  position: absolute;
  top: 12px; right: 12px;
  background: rgba(13,13,13,.7);
  border: 1px solid var(--border);
  border-radius: 50%;
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  color: var(--muted);
  font-size: 16px;
  transition: color var(--transition), background var(--transition);
  z-index: 1;
}
.product-card__wishlist:hover,
.product-card__wishlist.active { color: #e74c3c; background: rgba(231,76,60,.15); border-color: #e74c3c; }

.product-card__body { padding: 16px; }
.product-card__brand { font-size: 11px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; margin-bottom: 4px; }
.product-card__name { font-size: 15px; font-weight: 600; margin-bottom: 8px; line-height: 1.3; }
.product-card__rating { display: flex; align-items: center; gap: 6px; margin-bottom: 12px; }
.stars { color: var(--accent); font-size: 12px; letter-spacing: 1px; }
.product-card__rating span { font-size: 12px; color: var(--muted); }
.product-card__footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.product-card__price { font-size: 18px; font-weight: 700; }
.product-card__price s { font-size: 13px; color: var(--muted); font-weight: 400; margin-left: 4px; }
.product-card__add {
  background: var(--accent);
  border: none;
  color: #0d0d0d;
  font-weight: 700;
  font-size: 12px;
  padding: 8px 14px;
  border-radius: var(--radius);
  transition: transform var(--transition), box-shadow var(--transition);
}
.product-card__add:hover { transform: scale(1.05); box-shadow: 0 4px 14px rgba(232,201,109,.35); }
.product-card__add.added { background: #27ae60; color: #fff; }

/* ── Deals ── */
.deals { background: var(--bg2); }
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.deal-card {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 40px rgba(0,0,0,.5);
}
.deal-card--featured {
  grid-row: 1 / 3;
  background: linear-gradient(160deg, #1a1510 0%, #0d0d0d 100%);
  border-color: rgba(232,201,109,.2);
}
.deal-card__image {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 100px;
  padding: 32px;
  min-height: 180px;
}
.deal-card--featured .deal-card__image { font-size: 140px; min-height: 300px; }
.deal-card__body { padding: 20px; }
.deal-card__tag { font-size: 11px; font-weight: 700; color: var(--accent2); text-transform: uppercase; letter-spacing: .08em; margin-bottom: 8px; }
.deal-card__name { font-size: 17px; font-weight: 700; margin-bottom: 6px; line-height: 1.3; }
.deal-card--featured .deal-card__name { font-size: 24px; }
.deal-card__desc { font-size: 13px; color: var(--muted); margin-bottom: 16px; }
.deal-card__pricing { display: flex; align-items: baseline; gap: 10px; margin-bottom: 16px; }
.deal-card__price { font-size: 26px; font-weight: 800; color: var(--accent); }
.deal-card--featured .deal-card__price { font-size: 36px; }
.deal-card__was { font-size: 15px; color: var(--muted); text-decoration: line-through; }
.deal-card__save {
  position: absolute;
  top: 16px; right: 16px;
  background: var(--accent2);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 4px;
}
.deal-countdown {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
}
.deal-countdown__unit {
  background: rgba(255,255,255,.06);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 10px;
  text-align: center;
  min-width: 52px;
}
.deal-countdown__num {
  display: block;
  font-size: 20px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--accent);
}
.deal-countdown__label { font-size: 9px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }

.btn--sm { padding: 9px 18px; font-size: 13px; }

/* ── Categories strip ── */
.categories-strip {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.categories-strip::-webkit-scrollbar { display: none; }
.category-pill {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px 24px;
  width: 120px;
  cursor: pointer;
  transition: border-color var(--transition), transform var(--transition);
}
.category-pill:hover, .category-pill.active {
  border-color: var(--accent);
  transform: translateY(-2px);
}
.category-pill__icon { font-size: 32px; }
.category-pill__label { font-size: 12px; font-weight: 600; text-align: center; }

/* ── Editorial ── */
.editorial { background: var(--bg); }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.article-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.article-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 36px rgba(0,0,0,.4);
}
.article-card--featured { grid-row: 1 / 3; }
.article-card--side { flex-direction: row; }
.article-card__thumb {
  aspect-ratio: 16/9;
  background: var(--bg3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}
.article-card--featured .article-card__thumb { aspect-ratio: 16/10; font-size: 90px; }
.article-card--side .article-card__thumb { width: 130px; aspect-ratio: 1; font-size: 48px; }
.article-card__thumb-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 40%, rgba(13,13,13,.7));
}
.article-card__body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.article-card--side .article-card__body { padding: 16px; }
.article-card__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.article-card__meta time { font-size: 12px; color: var(--muted); }
.article-card__title { font-size: 18px; font-weight: 700; margin-bottom: 10px; line-height: 1.3; }
.article-card--featured .article-card__title { font-size: clamp(20px, 2.5vw, 26px); }
.article-card--side .article-card__title { font-size: 15px; }
.article-card__excerpt { font-size: 14px; color: var(--muted); line-height: 1.6; flex: 1; }
.article-card__read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
}
.article-card--side .article-card__excerpt { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* ── Newsletter ── */
.newsletter {
  background: linear-gradient(135deg, #141209 0%, #0d0d0d 100%);
  border-top: 1px solid rgba(232,201,109,.15);
  border-bottom: 1px solid rgba(232,201,109,.15);
  text-align: center;
  padding: 80px 0;
}
.newsletter h2 { font-size: clamp(24px, 3vw, 36px); font-weight: 800; margin-bottom: 12px; letter-spacing: -.02em; }
.newsletter p { color: var(--muted); max-width: 480px; margin: 0 auto 32px; }
.newsletter__form {
  display: flex;
  gap: 10px;
  max-width: 460px;
  margin: 0 auto;
}
.newsletter__input {
  flex: 1;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px 16px;
  color: var(--text);
  font-size: 14px;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter__input:focus { border-color: var(--accent); }
.newsletter__input::placeholder { color: var(--muted); }

/* ── Footer ── */
.footer {
  background: var(--bg2);
  border-top: 1px solid var(--border);
  padding: 60px 0 32px;
}
.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer__brand p { font-size: 14px; color: var(--muted); margin-top: 12px; line-height: 1.7; }
.footer__col h4 { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); margin-bottom: 16px; }
.footer__col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer__col ul a { font-size: 14px; color: var(--muted); transition: color var(--transition); }
.footer__col ul a:hover { color: var(--text); }
.footer__bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.footer__bottom p { font-size: 13px; color: var(--muted); }
.footer__socials { display: flex; gap: 12px; }
.footer__social {
  width: 36px; height: 36px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: flex; align-items: center; justify-content: center;
  color: var(--muted);
  font-size: 16px;
  transition: color var(--transition), border-color var(--transition);
}
.footer__social:hover { color: var(--text); border-color: var(--accent); }

/* ── Toast ── */
.toast-container {
  position: fixed;
  bottom: 24px; right: 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 999;
  pointer-events: none;
}
.toast {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius);
  padding: 12px 18px;
  font-size: 14px;
  color: var(--text);
  box-shadow: 0 4px 20px rgba(0,0,0,.5);
  animation: toastIn .3s ease forwards;
  max-width: 280px;
  pointer-events: auto;
}
.toast.removing { animation: toastOut .3s ease forwards; }
@keyframes toastIn  { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { from { opacity: 1; transform: none; } to { opacity: 0; transform: translateX(24px); } }

/* ── Mini Cart drawer ── */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.55);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}
.cart-overlay.open { opacity: 1; pointer-events: auto; }
.cart-drawer {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: 380px;
  background: var(--bg2);
  border-left: 1px solid var(--border);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform .3s ease;
}
.cart-drawer.open { transform: translateX(0); }
.cart-drawer__header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.cart-drawer__header h3 { font-size: 18px; font-weight: 700; }
.cart-drawer__close {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 22px;
  padding: 4px;
  transition: color var(--transition);
}
.cart-drawer__close:hover { color: var(--text); }
.cart-drawer__items { flex: 1; overflow-y: auto; padding: 16px 24px; }
.cart-item {
  display: flex;
  gap: 14px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.cart-item__thumb {
  width: 60px; height: 60px;
  background: var(--bg3);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 28px;
  flex-shrink: 0;
}
.cart-item__info { flex: 1; }
.cart-item__name { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.cart-item__price { font-size: 15px; font-weight: 700; color: var(--accent); }
.cart-item__remove { background: none; border: none; color: var(--muted); font-size: 18px; transition: color var(--transition); }
.cart-item__remove:hover { color: var(--accent2); }
.cart-empty { text-align: center; padding: 60px 24px; color: var(--muted); }
.cart-empty__icon { font-size: 48px; margin-bottom: 12px; }
.cart-drawer__footer {
  padding: 20px 24px;
  border-top: 1px solid var(--border);
}
.cart-drawer__total {
  display: flex;
  justify-content: space-between;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
}
.cart-drawer__total span:last-child { color: var(--accent); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--featured { grid-column: 1 / 3; grid-row: auto; }
  .footer__grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .navbar__nav { display: none; }
  .navbar__search { display: none; }
  .navbar__mobile-toggle { display: block; }
  .hero__inner { grid-template-columns: 1fr; }
  .hero__image-wrap { display: none; }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-card--featured { grid-row: auto; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--featured { grid-column: auto; }
  .newsletter__form { flex-direction: column; }
  .footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .cart-drawer { width: 100%; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  section { padding: 52px 0; }
  .products-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .product-card__image { font-size: 56px; }
}

