  color: var(--accent);
}
.deal-countdown__label { font-size: 9px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }

.btn--sm { padding: 9px 18px; font-size: 13px; }

/* ── Categories strip ── */
.categories-strip {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.categories-strip::-webkit-scrollbar { display: none; }
.category-pill {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px 24px;
  width: 120px;
