}
.category-pill__icon { font-size: 32px; }
.category-pill__label { font-size: 12px; font-weight: 600; text-align: center; }

/* ── Editorial ── */
.editorial { background: var(--bg); }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.article-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}
.article-card:hover {
