.cart-drawer__close:hover { color: var(--text); }
.cart-drawer__items { flex: 1; overflow-y: auto; padding: 16px 24px; }
.cart-item {
  display: flex;
  gap: 14px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.cart-item__thumb {
  width: 60px; height: 60px;
  background: var(--bg3);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 28px;
  flex-shrink: 0;
}
.cart-item__info { flex: 1; }
.cart-item__name { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.cart-item__price { font-size: 15px; font-weight: 700; color: var(--accent); }
.cart-item__remove { background: none; border: none; color: var(--muted); font-size: 18px; transition: color var(--transition); }
.cart-item__remove:hover { color: var(--accent2); }
.cart-empty { text-align: center; padding: 60px 24px; color: var(--muted); }
.cart-empty__icon { font-size: 48px; margin-bottom: 12px; }
.cart-drawer__footer {
  padding: 20px 24px;
  border-top: 1px solid var(--border);
}
.cart-drawer__total {
  display: flex;
  justify-content: space-between;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
}
.cart-drawer__total span:last-child { color: var(--accent); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--featured { grid-column: 1 / 3; grid-row: auto; }
  .footer__grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .navbar__nav { display: none; }
  .navbar__search { display: none; }
  .navbar__mobile-toggle { display: block; }
  .hero__inner { grid-template-columns: 1fr; }
  .hero__image-wrap { display: none; }
