+.hero__product-info p { color: var(--muted); font-size: 14px; margin-bottom: 14px; }
+.hero__price { font-size: 24px; font-weight: 800; color: var(--accent); }
+.hero__price s { font-size: 16px; color: var(--muted); font-weight: 400; margin-left: 8px; }
+
+.hero__floating-badge {
+  position: absolute;
+  top: 20px; right: 20px;
+  background: var(--accent2);
+  color: #fff;
+  font-size: 13px;
+  font-weight: 800;
+  padding: 8px 14px;
+  border-radius: 8px;
+  box-shadow: 0 4px 16px rgba(192,57,43,.4);
