+.product-card__wishlist:hover,
+.product-card__wishlist.active { color: #e74c3c; background: rgba(231,76,60,.15); border-color: #e74c3c; }
+
+.product-card__body { padding: 16px; }
+.product-card__brand { font-size: 11px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; margin-bottom: 4px; }
+.product-card__name { font-size: 15px; font-weight: 600; margin-bottom: 8px; line-height: 1.3; }
+.product-card__rating { display: flex; align-items: center; gap: 6px; margin-bottom: 12px; }
+.stars { color: var(--accent); font-size: 12px; letter-spacing: 1px; }
+.product-card__rating span { font-size: 12px; color: var(--muted); }
+.product-card__footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
+.product-card__price { font-size: 18px; font-weight: 700; }
+.product-card__price s { font-size: 13px; color: var(--muted); font-weight: 400; margin-left: 4px; }
+.product-card__add {
+  background: var(--accent);
+  border: none;
+  color: #0d0d0d;
+  font-weight: 700;
+  font-size: 12px;
+  padding: 8px 14px;
+  border-radius: var(--radius);
+  transition: transform var(--transition), box-shadow var(--transition);
+}
+.product-card__add:hover { transform: scale(1.05); box-shadow: 0 4px 14px rgba(232,201,109,.35); }
+.product-card__add.added { background: #27ae60; color: #fff; }
+
+/* ── Deals ── */
+.deals { background: var(--bg2); }
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 20px;
+}
+.deal-card {
+  background: var(--bg3);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  overflow: hidden;
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  transition: transform var(--transition), box-shadow var(--transition);
+}
+.deal-card:hover {
+  transform: translateY(-3px);
+  box-shadow: 0 12px 40px rgba(0,0,0,.5);
+}
+.deal-card--featured {
+  grid-row: 1 / 3;
+  background: linear-gradient(160deg, #1a1510 0%, #0d0d0d 100%);
+  border-color: rgba(232,201,109,.2);
+}
+.deal-card__image {
+  flex: 1;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 100px;
+  padding: 32px;
+  min-height: 180px;
+}
+.deal-card--featured .deal-card__image { font-size: 140px; min-height: 300px; }
+.deal-card__body { padding: 20px; }
+.deal-card__tag { font-size: 11px; font-weight: 700; color: var(--accent2); text-transform: uppercase; letter-spacing: .08em; margin-bottom: 8px; }
+.deal-card__name { font-size: 17px; font-weight: 700; margin-bottom: 6px; line-height: 1.3; }
+.deal-card--featured .deal-card__name { font-size: 24px; }
+.deal-card__desc { font-size: 13px; color: var(--muted); margin-bottom: 16px; }
+.deal-card__pricing { display: flex; align-items: baseline; gap: 10px; margin-bottom: 16px; }
+.deal-card__price { font-size: 26px; font-weight: 800; color: var(--accent); }
+.deal-card--featured .deal-card__price { font-size: 36px; }
+.deal-card__was { font-size: 15px; color: var(--muted); text-decoration: line-through; }
+.deal-card__save {
+  position: absolute;
+  top: 16px; right: 16px;
+  background: var(--accent2);
+  color: #fff;
+  font-size: 12px;
+  font-weight: 800;
+  padding: 4px 10px;
+  border-radius: 4px;
+}
+.deal-countdown {
+  display: flex;
+  gap: 8px;
+  margin-bottom: 18px;
+}
+.deal-countdown__unit {
+  background: rgba(255,255,255,.06);
+  border: 1px solid var(--border);
