+  text-align: center;
+  min-width: 52px;
+}
+.deal-countdown__num {
+  display: block;
+  font-size: 20px;
+  font-weight: 800;
+  font-variant-numeric: tabular-nums;
+  line-height: 1;
+  color: var(--accent);
+}
+.deal-countdown__label { font-size: 9px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
+
+.btn--sm { padding: 9px 18px; font-size: 13px; }
+
+/* ── Categories strip ── */
+.categories-strip {
+  display: flex;
+  gap: 14px;
+  overflow-x: auto;
+  padding-bottom: 4px;
+  scrollbar-width: none;
+}
+.categories-strip::-webkit-scrollbar { display: none; }
+.category-pill {
+  flex-shrink: 0;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 10px;
+  background: var(--bg2);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  padding: 20px 24px;
+  width: 120px;
+  cursor: pointer;
+  transition: border-color var(--transition), transform var(--transition);
+}
+.category-pill:hover, .category-pill.active {
+  border-color: var(--accent);
+  transform: translateY(-2px);
+}
+.category-pill__icon { font-size: 32px; }
+.category-pill__label { font-size: 12px; font-weight: 600; text-align: center; }
+
+/* ── Editorial ── */
+.editorial { background: var(--bg); }
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.6fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 20px;
+}
+.article-card {
+  background: var(--bg2);
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: transform var(--transition), box-shadow var(--transition);
+  cursor: pointer;
+}
+.article-card:hover {
+  transform: translateY(-3px);
+  box-shadow: 0 10px 36px rgba(0,0,0,.4);
+}
+.article-card--featured { grid-row: 1 / 3; }
+.article-card--side { flex-direction: row; }
+.article-card__thumb {
+  aspect-ratio: 16/9;
+  background: var(--bg3);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 64px;
+  flex-shrink: 0;
+  position: relative;
+  overflow: hidden;
+}
+.article-card--featured .article-card__thumb { aspect-ratio: 16/10; font-size: 90px; }
+.article-card--side .article-card__thumb { width: 130px; aspect-ratio: 1; font-size: 48px; }
+.article-card__thumb-overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to bottom, transparent 40%, rgba(13,13,13,.7));
+}
+.article-card__body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
+.article-card--side .article-card__body { padding: 16px; }
+.article-card__meta {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  margin-bottom: 10px;
+}
+.article-card__meta time { font-size: 12px; color: var(--muted); }
+.article-card__title { font-size: 18px; font-weight: 700; margin-bottom: 10px; line-height: 1.3; }
+.article-card--featured .article-card__title { font-size: clamp(20px, 2.5vw, 26px); }
+.article-card--side .article-card__title { font-size: 15px; }
+.article-card__excerpt { font-size: 14px; color: var(--muted); line-height: 1.6; flex: 1; }
+.article-card__read-more {
+  display: inline-flex;
