+        <div class="cart-item__name">${c.name}</div>
+        <div class="cart-item__price">${fmt(c.price)} × ${c.qty}</div>
+      </div>
+      <button class="cart-item__remove" data-remove="${c.id}">×</button>
+    </div>
+  `).join('');
+
+  const total = state.cart.reduce((a, c) => a + c.price * c.qty, 0);
+  document.getElementById('cartTotal').textContent = fmt(total);
+
+  container.querySelectorAll('[data-remove]').forEach(btn => {
+    btn.addEventListener('click', () => removeFromCart(+btn.dataset.remove));
+  });
+}
+
+// ── Wishlist ────────────────────────────────────────────────────────────────
+function toggleWishlist(id, btn) {
+  if (state.wishlist.has(id)) {
+    state.wishlist.delete(id);
+    btn.classList.remove('active');
+    btn.textContent = '♡';
+    showToast('Removed from wishlist');
+  } else {
+    state.wishlist.add(id);
+    btn.classList.add('active');
+    btn.textContent = '♥';
+    showToast('❤️ Added to wishlist');
+  }
+}
+
+// ── Cart Drawer ──────────────────────────────────────────────────────────────
+function openCart()  {
+  document.getElementById('cartDrawer').classList.add('open');
+  document.getElementById('cartOverlay').classList.add('open');
+  document.body.style.overflow = 'hidden';
+}
+function closeCart() {
+  document.getElementById('cartDrawer').classList.remove('open');
+  document.getElementById('cartOverlay').classList.remove('open');
+  document.body.style.overflow = '';
+}
+
+// ── Countdown ────────────────────────────────────────────────────────────────
+function startCountdown() {
+  const endTime = Date.now() + (3 * 3600 + 47 * 60 + 22) * 1000;
+  function tick() {
+    const diff = Math.max(0, endTime - Date.now());
+    const h = Math.floor(diff / 3600000);
+    const m = Math.floor((diff % 3600000) / 60000);
+    const s = Math.floor((diff % 60000) / 1000);
+    const pad = n => String(n).padStart(2, '0');
+    const el = document.getElementById('countdown');
+    if (el) {
+      el.querySelector('[data-unit=h]').textContent = pad(h);
+      el.querySelector('[data-unit=m]').textContent = pad(m);
+      el.querySelector('[data-unit=s]').textContent = pad(s);
+    }
+  }
+  tick();
+  setInterval(tick, 1000);
+}
+
+// ── Category filter ───────────────────────────────────────────────────────────
+function initCategories() {
+  document.querySelectorAll('.category-pill').forEach(pill => {
+    pill.addEventListener('click', () => {
+      document.querySelectorAll('.category-pill').forEach(p => p.classList.remove('active'));
+      pill.classList.add('active');
+    });
+  });
+}
+
+// ── Newsletter ─────────────────────────────────────────────────────────────
+function initNewsletter() {
+  const form = document.getElementById('newsletterForm');
+  if (!form) return;
+  form.addEventListener('submit', e => {
+    e.preventDefault();
+    const input = form.querySelector('input');
+    if (!input.value.trim()) return;
+    showToast('🎉 You\'re subscribed! Welcome aboard.');
+    input.value = '';
+  });
+}
+
+// ── Sticky navbar shadow on scroll ─────────────────────────────────────────
+function initScrollEffects() {
+  const nav = document.querySelector('.navbar');
+  window.addEventListener('scroll', () => {
+    nav.style.boxShadow = window.scrollY > 10
+      ? '0 4px 30px rgba(0,0,0,.5)'
+      : 'none';
+  }, { passive: true });
+}
+
+// ── Mobile nav ─────────────────────────────────────────────────────────────
+function initMobileNav() {
+  const toggle = document.getElementById('mobileNavToggle');
+  const nav    = document.getElementById('mainNav');
+  if (!toggle || !nav) return;
+  toggle.addEventListener('click', () => {
+    const open = nav.style.display === 'flex';
+    nav.style.display = open ? '' : 'flex';
+    nav.style.flexDirection = 'column';
+    nav.style.position = 'absolute';
+    nav.style.top = '64px';
+    nav.style.left = '0';
+    nav.style.right = '0';
+    nav.style.background = 'var(--bg)';
+    nav.style.borderBottom = '1px solid var(--border)';
+    nav.style.padding = '16px 24px';
+    nav.style.gap = '16px';
+    toggle.textContent = open ? '☰' : '✕';
+  });
+}
+
+// ── Deal card CTAs ──────────────────────────────────────────────────────────
+function initDealButtons() {
+  document.querySelectorAll('[data-deal-add]').forEach(btn => {
+    btn.addEventListener('click', () => {
+      const productId = +btn.dataset.dealAdd;
+      const product = products.find(p => p.id === productId);
+      if (!product) return;
+      addToCart(productId, btn);
+    });
+  });
+}
+
+// ── Init ────────────────────────────────────────────────────────────────────
+document.addEventListener('DOMContentLoaded', () => {
+  renderProducts();
+  renderCartItems();
+  startCountdown();
+  initCategories();
+  initNewsletter();
+  initScrollEffects();
+  initMobileNav();
+  initDealButtons();
+
+  document.getElementById('cartBtn')?.addEventListener('click', openCart);
+  document.getElementById('cartClose')?.addEventListener('click', closeCart);
+  document.getElementById('cartOverlay')?.addEventListener('click', closeCart);
+
+  // Hero add to cart
+  document.getElementById('heroAddBtn')?.addEventListener('click', () => {
+    addToCart(1, document.getElementById('heroAddBtn'));
+  });
+});
+
')

